868	/**
869	 * Normaliza um valor de `produtos_master.setor` para comparação: trim,
870	 * minúsculas e remoção de acentos (NFD). O banco tem caixa/acentuação
871	 * inconsistentes no MESMO setor (ex.: "CÂMARA FRIA" e "Câmara Fria") —
872	 * toda comparação de setor DEVE passar por aqui.
873	 */
874	export function normalizeSetor(value: string | null | undefined): string {
875	  return (value ?? '')
876	    .normalize('NFD')
877	    .replace(/\p{M}/gu, '')
878	    .trim()
879	    .toLowerCase();
880	}
