907	/**
908	 * Classifica linhas de estoque em alertas por loja (apenas produtos ATIVOS
909	 * devem chegar aqui — o JOIN com `produtos_master.ativo = true` é feito na
910	 * query). Regras (critério existente do projeto, sem schema novo):
911	 * - SÓ setor {@link TV_ALERT_SETOR} entra em alerta (regra do CTO
912	 *   2026-06-05: alertas só do setor de produtos vendáveis) — comparação
913	 *   normalizada client-side porque a caixa no banco é inconsistente;
914	 * - zerado (vermelho): quantidade ≤ 0 com mínimo definido (positivo);
915	 * - abaixo do mínimo (âmbar): quantidade entre 0 exclusivo e o mínimo.
916	 */
917	export function buildStockSummary(rows: StockRow[]): Map<number, StockDetail> {
918	  const out = new Map<number, StockDetail>();
919	  for (const row of rows) {
920	    if (row.loja_id == null) continue;
921	    if (!isTvAlertSetor(row.setor)) continue; // fora do setor vendável → sem alerta
922	    const min = row.quantidade_minima ?? 0;
923	    if (min <= 0) continue; // sem mínimo definido → sem alerta
924	    const qty = row.quantidade_atual ?? 0;
925	    if (qty >= min) continue; // dentro do normal
926	    let detail = out.get(row.loja_id);
927	    if (!detail) {
928	      detail = { zerados: 0, abaixoMinimo: 0, itens: [] };
929	      out.set(row.loja_id, detail);
930	    }
931	    const zerado = qty <= 0;
932	    if (zerado) detail.zerados += 1;
933	    else detail.abaixoMinimo += 1;
934	    detail.itens.push({
935	      produtoNome: row.produtoNome,
936	      quantidade: qty,
937	      quantidadeMinima: min,
938	      zerado,
939	    });
940	  }
941	  return out;
942	}
