985	/**
986	 * Corrige o `loja_id` das linhas de flash-vendas.
987	 *
988	 * LANDMINE conhecida: a edge function `degust-pos-financial` (deployada)
989	 * só mapeia os códigos Degust 1→4 e 2→5; códigos não mapeados passam CRUS
990	 * (ex.: BSB Shopping = código Degust 3 chega como `loja_id: 3`, colidindo
991	 * com Asa Norte). Aqui remapeamos usando a tabela `degust_stores`
992	 * (degust_loja_codigo → loja_id), que é a fonte de verdade em runtime.
993	 *
994	 * - Linha cujo loja_id já é uma loja Degust conhecida → mantém.
995	 * - Linha cujo loja_id corresponde a um código Degust → remapeia.
996	 * - Caso contrário → descarta (não corromper outra loja).
997	 */
998	export function remapFlashLojaIds(
999	  rows: FlashRow[],
1000	  degustCodeToLoja: ReadonlyMap<number, number>,
1001	  knownDegustLojaIds: ReadonlySet<number>,
1002	): FlashRow[] {
1003	  const out: FlashRow[] = [];
1004	  for (const row of rows) {
1005	    if (knownDegustLojaIds.has(row.loja_id)) {
1006	      out.push(row);
1007	      continue;
1008	    }
1009	    const mapped = degustCodeToLoja.get(row.loja_id);
1010	    if (mapped != null) {
1011	      out.push({ ...row, loja_id: mapped });
1012	    }
1013	    // não mapeável → descartado de propósito (ver TSDoc)
1014	  }
1015	  return out;
1016	}
