/**
 * Meta SEMANAL da loja (semana corrente seg-dom do mês CORRENTE), derivada
 * da meta mensal da loja em `metas_mensais` com a MESMA redistribuição de
 * {@link TvWeeklyGoal} (déficit/superávit das semanas passadas realoca os
 * targets restantes).
 */
export interface TvStoreWeeklyGoal {
  /** Meta da semana corrente (redistribuída — pode divergir do proporcional). */
  target: number;
  /** Realizado na semana corrente (segunda → agora, incluindo hoje live). */
  achieved: number;
  /** % da meta semanal (achieved/target × 100; null se target ≤ 0). */
  pct: number | null;
}

/** Acompanhamento do mês corrente (R3+R4): MTD, meta mensal e semanas. */

  deliverySplit?: { delivery: number; balcao: number } | null;
  /**
   * Meta SEMANAL da loja (semana corrente do mês CORRENTE, independente do
   * período/offset exibido — mesma semântica do monthProgress). Target vem
   * da redistribuição da meta mensal da loja ({@link TvStoreWeeklyGoal});
   * `achieved` soma segunda → agora, com hoje = valor live do flash quando
   * disponível. null/ausente quando a loja não tem meta mensal cadastrada
   * no mês corrente ou não tem canal de venda com dado diário (Degust).
   */
  weeklyGoal?: { target: number; achieved: number; pct: number | null } | null;
}

