/**
 * Meta semanal de UMA loja na SEMANA CORRENTE: aplica {@link weeklyTargets}
 * (mesma redistribuição da meta mensal usada no monthProgress da rede) ao
 * realizado diário da loja e extrai o segmento corrente.
 *
 * - `target` = meta redistribuída da semana corrente (semana 1 abaixo da
 *   meta ⇒ target sobe; acima ⇒ desce);
 * - `achieved` = soma do realizado nos dias do segmento corrente (segunda →
 *   agora — dias futuros não têm entrada no mapa e contam 0);
 * - `pct` = achieved/target × 100, null se target ≤ 0 (sem % honesto).
 *
 * Retorna null quando não há meta mensal positiva cadastrada ou quando
 * `now` está fora de qualquer segmento do mês (não acontece na prática).
 */
export function currentWeekGoal(
  metaMensal: number | null | undefined,
  realizadoPorDia: Map<string, number>,
  now: Date,
): TvStoreWeeklyGoal | null {
  if (metaMensal == null || metaMensal <= 0) return null;
  const current = weeklyTargets(metaMensal, realizadoPorDia, now).find(
    (w) => w.isCurrent,
  );
  if (!current) return null;
  const achieved = current.achieved ?? 0;
  return {
    target: current.target,
    achieved,
    pct: current.target > 0 ? (achieved / current.target) * 100 : null,
  };
}

