/** MTD da rede: total por DATA (rede) + total por LOJA + diário por LOJA. */
interface MtdSalesResult {
  /** data (YYYY-MM-DD) → R$ da REDE no dia (lojas Degust somadas). */
  byDate: Map<string, number>;
  /** loja_id → R$ acumulado no mês. */
  byLoja: Map<number, number>;
  /**
   * loja_id → data → R$ oficial do dia (01 → hoje). Base do `weeklyGoal`
   * por loja — MESMA passada de agregação do `byDate` da rede, sem fetch
   * adicional.
   */
  dailyByLoja: Map<number, Map<string, number>>;
}

async function fetchMtdSales(ctx: TvContext): Promise<MtdSalesResult> {
  const now = new Date();
  const from = toIsoDateLocal(new Date(now.getFullYear(), now.getMonth(), 1));
  const to = toIsoDateLocal(now);
  const data = await callDegustEdge({ startDate: from, endDate: to });
  const byDate = new Map<string, number>();
  const byLoja = new Map<number, number>();
  const dailyByLoja = new Map<number, Map<string, number>>();
  for (const d of data.daily ?? []) {
    if (!ctx.degustLojaIds.has(d.loja_id)) continue;
    const valor = d.total_faturado ?? 0;
    byDate.set(d.data, (byDate.get(d.data) ?? 0) + valor);
    byLoja.set(d.loja_id, (byLoja.get(d.loja_id) ?? 0) + valor);
    let porDia = dailyByLoja.get(d.loja_id);
    if (!porDia) {
      porDia = new Map<string, number>();
      dailyByLoja.set(d.loja_id, porDia);
    }
    porDia.set(d.data, (porDia.get(d.data) ?? 0) + valor);
  }
  return { byDate, byLoja, dailyByLoja };
}

