describe('currentWeekGoal (meta semanal POR LOJA — semana corrente)', () => {
  // qui 11/06/2026 — semana 2 do mês (08-14/06) é a corrente
  const now = new Date(2026, 5, 11, 15, 0, 0);

  it('semana 1 abaixo da meta ⇒ target corrente > proporcional; achieved soma seg→hoje', () => {
    const META = 100_000;
    const realizado = new Map<string, number>();
    // Semana 1 (01-07/06): 2k/dia = 14k (abaixo do proporcional 23.333,33)
    for (let d = 1; d <= 7; d += 1) {
      realizado.set(`2026-06-${String(d).padStart(2, '0')}`, 2_000);
    }
    // Semana corrente (08-11/06): 3k/dia = 12k até agora
    for (let d = 8; d <= 11; d += 1) {
      realizado.set(`2026-06-${String(d).padStart(2, '0')}`, 3_000);
    }
    const goal = currentWeekGoal(META, realizado, now);
    if (!goal) throw new Error('weeklyGoal deveria existir com meta positiva');
    // Redistribuição: (100k − 14k) × 7/23 ≈ 26.173,91 > base 100k × 7/30
    expect(goal.target).toBeCloseTo((86_000 * 7) / 23, 2);
    expect(goal.target).toBeGreaterThan((META * 7) / 30);
    expect(goal.achieved).toBeCloseTo(12_000, 5);
    expect(goal.pct).toBeCloseTo((12_000 / goal.target) * 100, 5);
  });

  it('sem meta mensal cadastrada (null/0/negativa) → null', () => {
    const realizado = new Map<string, number>([['2026-06-10', 5_000]]);
    expect(currentWeekGoal(null, realizado, now)).toBeNull();
    expect(currentWeekGoal(undefined, realizado, now)).toBeNull();
    expect(currentWeekGoal(0, realizado, now)).toBeNull();
    expect(currentWeekGoal(-10, realizado, now)).toBeNull();
  });

  it('meta já superada na semana 1 ⇒ target ≤ 0 e pct null (sem % honesto)', () => {
    const realizado = new Map<string, number>([['2026-06-02', 110_000]]);
    const goal = currentWeekGoal(100_000, realizado, now);
    if (!goal) throw new Error('weeklyGoal deveria existir com meta positiva');
    expect(goal.target).toBeLessThan(0);
    expect(goal.pct).toBeNull();
    expect(goal.achieved).toBe(0); // nada vendido na semana corrente ainda
  });

  it('reproduz os números reais de jun/2026 (sanity da spec): (meta − sem1) × 7/23', () => {
    // Metas mensais e realizado da semana 01-07/06 fornecidos pelo CTO;
    // targets esperados da semana corrente conforme a fórmula da spec.
    const cases = [
      { lojaId: 2, meta: 480_000, semana1: 82_127.37, esperado: 121_091.67 },
      { lojaId: 3, meta: 225_000, semana1: 39_791.4, esperado: 56_367.4 },
      { lojaId: 4, meta: 300_000, semana1: 50_012.34, esperado: 76_083.71 },
      { lojaId: 5, meta: 240_000, semana1: 39_073.44, esperado: 61_151.13 },
      { lojaId: 6, meta: 255_000, semana1: 58_355.1, esperado: 59_848.01 },
    ];
    for (const { meta, semana1, esperado } of cases) {
      const realizado = new Map<string, number>([['2026-06-02', semana1]]);
      const goal = currentWeekGoal(meta, realizado, now);
      if (!goal) throw new Error('weeklyGoal deveria existir com meta positiva');
      // Exato pela fórmula (semana 1 encerrada redistribui sobre 23 dias)
      expect(goal.target).toBeCloseTo(((meta - semana1) * 7) / 23, 6);
      // E ≈ os valores de referência (entradas de sem1 arredondadas a 2
      // casas → tolerância < R$ 1 sobre os targets de referência)
      expect(Math.abs(goal.target - esperado)).toBeLessThan(1);
    }
  });
});

