// Estado mutável dos mocks (hoisted: a factory do vi.mock roda antes do
// corpo do arquivo). Por default: tabelas vazias e edge fora do ar (503) —
// preserva o comportamento dos testes de snapshot vazio.
const mockState = vi.hoisted(() => ({
  tables: {} as Record<string, unknown[]>,
  /** Handler da edge `degust-pos-financial` (null = HTTP 503). */
  edge: null as ((body: Record<string, unknown>) => unknown) | null,
}));

// Mock leve do client Supabase: builder encadeável thenable que resolve
// com as linhas registradas em `mockState.tables` (vazio por default).
vi.mock('@/integrations/supabase/client', () => {
  type QueryResult = { data: unknown[]; error: null };
  const CHAIN_METHODS = [
    'select',
    'eq',
    'gt',
    'gte',
    'lt',
    'lte',
    'in',
    'or',
    'is',
    'not',
    'order',
    'limit',
    'range',
  ] as const;

  const makeBuilder = (table: string): Record<string, unknown> => {
    const builder: Record<string, unknown> = {};
    for (const method of CHAIN_METHODS) {
      builder[method] = () => builder;
    }
    builder.then = (onFulfilled: (value: QueryResult) => unknown) =>
      Promise.resolve({
        data: mockState.tables[table] ?? [],
        error: null,
      }).then(onFulfilled);
    return builder;
  };

  return {
    supabase: {
      from: (table: string) => makeBuilder(table),
      auth: { getSession: async () => ({ data: { session: null } }) },
      functions: {
        invoke: async () => ({ data: { flash: [] }, error: null }),
      },
    },
  };
});

