// ─────────────────────────────────────────────────────────────────────────────
// weeklyGoal por loja (meta semanal do mês corrente)
// ─────────────────────────────────────────────────────────────────────────────

const pad = (n: number) => String(n).padStart(2, '0');
const isoLocal = (d: Date) =>
  `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
const plusDays = (d: Date, n: number) => {
  const out = new Date(d);
  out.setDate(out.getDate() + n);
  return out;
};

interface DailyRow {
  data: string;
  loja_id: number;
  total_faturado: number;
  total_cupons: number;
}

/**
 * Fixture relativa a HOJE (robusta a qualquer data de execução):
 * - loja 4 com meta mensal própria (100k) + diário oficial de R$ 1.000 nos
 *   dias JÁ FECHADOS da semana corrente + R$ 999 oficial parcial de hoje +
 *   flash live de R$ 1.500 hoje;
 * - loja 3 Degust SEM linha própria em `metas_mensais` (só a linha da rede);
 * - quando a semana corrente não começa no dia 1º, um dia de semana ANTERIOR
 *   do mês entra com R$ 7.777 (redistribui o target, fora do achieved).
 */
function setupWeeklyGoalFixture() {
  const now = new Date();
  const todayIso = isoLocal(now);
  const firstOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
  const dowFromMonday = (now.getDay() + 6) % 7;
  const monday = plusDays(now, -dowFromMonday);
  const weekStart =
    monday.getTime() < firstOfMonth.getTime() ? firstOfMonth : monday;

  const closedDays: string[] = [];
  for (let d = new Date(weekStart); isoLocal(d) < todayIso; d = plusDays(d, 1)) {
    closedDays.push(isoLocal(d));
  }

  const daily: DailyRow[] = [
    ...closedDays.map((data) => ({
      data,
      loja_id: 4,
      total_faturado: 1_000,
      total_cupons: 10,
    })),
    // hoje TEM oficial parcial (999) — no live o flash (1.500) deve prevalecer
    { data: todayIso, loja_id: 4, total_faturado: 999, total_cupons: 9 },
  ];
  if (weekStart.getTime() > firstOfMonth.getTime()) {
    daily.push({
      data: isoLocal(firstOfMonth),
      loja_id: 4,
      total_faturado: 7_777,
      total_cupons: 7,
    });
  }

  mockState.tables = {
    lojas: [
      { id: 4, nome: 'Momma Lago Sul', tipo: 'Loja' },
      { id: 3, nome: 'Momma Asa Norte', tipo: 'Loja' },
    ],
    degust_stores: [
      { loja_id: 4, degust_loja_codigo: 1 },
      { loja_id: 3, degust_loja_codigo: 5 },
    ],
    metas_mensais: [
      // Linha da REDE (loja_id NULL) NÃO vira meta de loja nenhuma
      {
        loja_id: null,
        ano: now.getFullYear(),
        mes: now.getMonth() + 1,
        valor_meta: 999_999,
      },
      {
        loja_id: 4,
        ano: now.getFullYear(),
        mes: now.getMonth() + 1,
        valor_meta: 100_000,
      },
    ],
  };

  const brToday = `${pad(now.getDate())}/${pad(now.getMonth() + 1)}/${now.getFullYear()} 12:00:00`;
  mockState.edge = (body) => {
    if (body.includeHourly) return { hourly: [] };
    if (body.includeDeliverySplit) return { deliverySplit: [] };
    return {
      flash: [
        {
          loja_id: 4,
          nome_loja: 'Momma Lago Sul',
          total_vendas: 1_500,
          total_cupons: 12,
          ticket_medio: 125,
          qtd_produtos: 0,
          caixa_aberto: true,
          ultima_atualizacao: brToday,
        },
      ],
      daily,
    };
  };

  return { now, todayIso, closedDays, daily };
}

describe('useTvDashboardData — weeklyGoal por loja (meta semanal)', () => {
  it('live: loja com meta tem weeklyGoal — achieved soma seg→hoje com HOJE do flash; loja sem meta → null', async () => {
    const { now, todayIso, closedDays, daily } = setupWeeklyGoalFixture();
    const { result, unmount } = renderHook(() => useTvDashboardData(), {
      wrapper: createWrapper(),
    });

    // seg→ontem oficiais (1k/dia) + hoje pelo FLASH (1.500, não o 999 oficial)
    const expectedAchieved = closedDays.length * 1_000 + 1_500;
    await waitFor(() => {
      expect(
        result.current.stores.find((s) => s.lojaId === 4)?.weeklyGoal?.achieved,
      ).toBe(expectedAchieved);
    });

    const goal = result.current.stores.find((s) => s.lojaId === 4)?.weeklyGoal;
    if (!goal) throw new Error('weeklyGoal ausente para a loja com meta');
    // Target = MESMA redistribuição do helper puro sobre o mesmo realizado
    // (déficit/superávit das semanas passadas realoca a meta da corrente).
    const realizado = new Map<string, number>(
      daily.map((d) => [d.data, d.total_faturado]),
    );
    realizado.set(todayIso, 1_500); // hoje = flash live
    const esperado = currentWeekGoal(100_000, realizado, now);
    if (!esperado) throw new Error('fixture inválida: meta positiva sem goal');
    expect(goal.target).toBeCloseTo(esperado.target, 6);
    expect(goal.pct).toBeCloseTo((expectedAchieved / esperado.target) * 100, 6);

    // Loja Degust SEM linha própria em metas_mensais → null (rede não conta)
    expect(
      result.current.stores.find((s) => s.lojaId === 3)?.weeklyGoal,
    ).toBeNull();
    unmount();
  });

  it('histórico (offset < 0): weeklyGoal mantém os dados oficiais do MTD, sem flash', async () => {
    const { closedDays } = setupWeeklyGoalFixture();
    const { result, unmount } = renderHook(
      () => useTvDashboardData('today', -1),
      { wrapper: createWrapper() },
    );

    // Sem flash (modo passado): hoje entra com o oficial parcial (999)
    const expectedAchieved = closedDays.length * 1_000 + 999;
    await waitFor(() => {
      expect(
        result.current.stores.find((s) => s.lojaId === 4)?.weeklyGoal?.achieved,
      ).toBe(expectedAchieved);
    });
    expect(result.current.isLive).toBe(false);
    unmount();
  });
});
